import { ref, computed, onMounted, onUnmounted, watch } from "vue";
import { ElCarousel, ElCarouselItem, ElButton, ElMenu, ElMenuItem, ElSelect, ElOption, ElRow, ElCol, ElCard, ElPagination, ElDialog, ElMessage } from "element-plus";
import { useRouter } from "vue-router"; // 导入路由
import { useStore } from "vuex"; // 导入 Vuex Store
import axios from "axios";
import { User, ShoppingCart, List, People, SwitchButton } from "@element-plus/icons-vue"; // 导入需要的图标

const API_BASE_URL = "http://localhost:5000"; // 添加 API 基础 URL

export default {
  __name: 'HomePage',
  setup(__props, {
    expose: __expose
  }) {
    __expose();
    const router = useRouter(); // 获取路由对象
    const store = useStore(); // 获取 Vuex Store
    const searchQuery = ref(""); // 搜索查询
    const selectedSort = ref("default-sort"); // 默认排序方式
    const currentPage = ref(1); // 当前页码
    const itemsPerPage = ref(8); // 每页显示的商品数量
    const sortedProducts = computed(() => {
      const products = store.getters.allProducts || [];
      console.log("当前产品列表:", products);
      switch (selectedSort.value) {
        case "low-to-high":
          return [...products].sort((a, b) => a.price - b.price);
        case "high-to-low":
          return [...products].sort((a, b) => b.price - a.price);
        case "hot-to-high":
          return [...products].sort((a, b) => b.sales - a.sales);
        default:
          return products;
      }
    });
    const ads = ref([{
      image: "/assets/苹果13.png"
    }, {
      image: "/assets/苹果15Pro.png"
    }, {
      image: "/assets/微软二合一ipad.png"
    }]);
    const goToProfile = () => {
      router.push({
        name: "UserPage"
      }); // 跳转到个人中心页面
    };

    // 获取产品数据
    const fetchProductData = async () => {
      try {
        await store.dispatch("FetchProducts");
        console.log("产品数据获取成功");
      } catch (error) {
        console.error("获取产品数据失败:", error);
      }
    };
    // 添加跳转到购物车的功能
    const goToCart = () => {
      router.push({
        name: "CartPage"
      }); // 跳转到购物车页面
    };

    // 添加跳转到我的订单的功能
    const goToOrders = () => {
      // 使用路径导航
      router.push({
        name: "OrderPage"
      });
    };

    // 计算属性获取用户昵称
    const userNickname = computed(() => store.getters.userNickname);
    // 计算属性获取用户头像
    const userAvatar = computed(() => {
      const avatar = store.getters.userAvatar;
      if (!avatar) {
        return "/assets/avatar.png";
      }
      if (avatar === "/assets/avatar.png") {
        return avatar;
      }
      return avatar.startsWith("http") ? avatar : `http://localhost:5000${avatar}`;
    });

    // 获取当前页的产品
    const paginatedProducts = computed(() => {
      const start = (currentPage.value - 1) * itemsPerPage.value;
      const end = start + itemsPerPage.value;
      return sortedProducts.value.slice(start, end);
    });

    // 分页功能变化时的处理函数
    const handlePageChange = newPage => {
      currentPage.value = newPage; // 更新当前页
    };

    // 搜索功能
    const applySearch = async () => {
      console.log("搜索产品:", searchQuery.value);
      try {
        if (searchQuery.value.trim()) {
          await store.dispatch("SearchProducts", searchQuery.value);
        } else {
          await store.dispatch("FetchProducts");
        }
        currentPage.value = 1; // 重置页码
      } catch (error) {
        console.error("搜索产品失败:", error);
      }
    };

    // 跳转到首页并刷新
    const goHome = () => {
      window.location.reload(); // 强制刷新页面
    };

    // 跳转到商品详情
    const viewProductDetails = product => {
      console.log(`Navigating to product with ID: ${product.id}`); // 调试输出
      router.push(`/product/${product.id}`);
    };

    // 选择分类
    const selectCategory = async category => {
      console.log(`选择了分类: ${category}`);
      try {
        if (category) {
          await store.dispatch("FetchProductsByCategory", category);
        } else {
          await store.dispatch("FetchProducts");
        }
        currentPage.value = 1; // 重置页码
      } catch (error) {
        console.error("获取分类产品失败:", error);
      }
    };

    // 退出登录功能
    const logout = () => {
      console.log("用户已注销");
      store.commit("clearUser"); // 清空用户信息
      router.push({
        name: "Login"
      }); // 跳转到登录页面
    };

    // 拼团相关
    const groupBuyDialogVisible = ref(false);
    const myGroupBuys = ref([]);
    const timers = ref({}); // 存储所有计时器

    // 显示我的拼团对话框
    const showMyGroupBuys = async () => {
      groupBuyDialogVisible.value = true;
      await fetchMyGroupBuys();
    };

    // 获取我的拼团列表
    const fetchMyGroupBuys = async () => {
      try {
        const response = await axios.get(`${API_BASE_URL}/api/group-buys/user`, {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("token")}`
          }
        });
        if (response.data.code === 200) {
          console.log("完整的拼团数据:", response.data.data);
          myGroupBuys.value = response.data.data.map(group => {
            // 确保 requiredSize 至少为 5
            group.requiredSize = group.requiredSize || 5;
            console.log("处理拼团:", group.id, {
              status: group.status,
              currentSize: group.currentSize,
              requiredSize: group.requiredSize,
              remainingSeconds: group.remainingSeconds
            });

            // 检查拼团状态
            if (group.status === "IN_PROGRESS") {
              const currentSize = Number(group.currentSize);
              const requiredSize = Number(group.requiredSize);
              console.log(`拼团${group.id} - 当前人数:${currentSize}, 要求人数:${requiredSize}, 类型:`, {
                currentSizeType: typeof group.currentSize,
                requiredSizeType: typeof group.requiredSize
              });

              // 只有在人数严格等于要求时才标记为成功
              if (currentSize === requiredSize) {
                console.log(`拼团${group.id}达到人数要求，标记为成功`);
                group.status = "SUCCESS";
              }
              // 只有在时间到期且人数未达到要求时才标记为失败
              else if (group.remainingSeconds <= 0 && currentSize < requiredSize) {
                console.log(`拼团${group.id}时间到期且人数未达标，标记为失败`);
                group.status = "FAILED";
              } else {
                console.log(`拼团${group.id}保持进行中状态`);
              }
            }
            return group;
          });

          // 为每个进行中的拼团启动倒计时
          myGroupBuys.value.forEach(group => {
            if (group.status === "IN_PROGRESS" && group.remainingSeconds > 0) {
              startGroupCountdown(group);
            }
          });
        }
      } catch (error) {
        // 静默失败，不显示任何错误信息
      }
    };

    // 修改倒计时逻辑
    const startGroupCountdown = group => {
      console.log(`开始拼团${group.id}的倒计时`);
      const timer = setInterval(() => {
        // 确保 requiredSize 至少为 5
        group.requiredSize = group.requiredSize || 5;
        const currentSize = Number(group.currentSize);
        const requiredSize = Number(group.requiredSize);
        console.log(`拼团${group.id}倒计时检查 - 当前人数:${currentSize}, 要求人数:${requiredSize}, 剩余时间:${group.remainingSeconds}`);
        if (group.remainingSeconds <= 0) {
          clearInterval(timer);
          if (currentSize < requiredSize) {
            console.log(`拼团${group.id}时间到期且人数未达标，标记为失败`);
            group.status = "FAILED";
          }
          return;
        }
        if (currentSize === requiredSize) {
          clearInterval(timer);
          console.log(`拼团${group.id}达到人数要求，标记为成功`);
          group.status = "SUCCESS";
          return;
        }
        group.remainingSeconds--;
      }, 1000);

      // 保存定时器ID以便在组件销毁时清除
      timers.value[group.id] = timer;
    };

    // 格式化拼团状态
    const formatGroupStatus = status => {
      const statusMap = {
        IN_PROGRESS: "进行中",
        COMPLETED: "拼团成功",
        FAILED: "拼团失败"
      };
      return statusMap[status] || status;
    };

    // 格式化剩余时间
    const formatTime = seconds => {
      if (seconds == null || isNaN(seconds)) return "00:00:00";
      const hours = Math.floor(seconds / 3600);
      const minutes = Math.floor(seconds % 3600 / 60);
      const remainingSeconds = seconds % 60;
      return `${hours.toString().padStart(2, "0")}:${minutes.toString().padStart(2, "0")}:${remainingSeconds.toString().padStart(2, "0")}`;
    };

    // 复制邀请码
    const copyInviteCode = async inviteCode => {
      try {
        await navigator.clipboard.writeText(inviteCode);
        ElMessage.success("邀请码已复制到剪贴板");
      } catch (error) {
        console.error("复制失败:", error);
        ElMessage.error("复制失败，请手动复制");
      }
    };

    // 获取参与者头像
    const getParticipantAvatar = participant => {
      console.log("处理头像的参与者数据:", participant); // 添加调试日志
      if (!participant || !participant.avatar) {
        return "/assets/avatar.png";
      }

      // 如果头像路径是相对路径，添加API基础URL
      if (participant.avatar.startsWith("/")) {
        return `${API_BASE_URL}${participant.avatar}`;
      }

      // 如果是完整的URL或默认头像，直接返回
      return participant.avatar;
    };

    // 在组件挂载时获取产品数据
    onMounted(() => {
      fetchProductData();
    });

    // 在对话框关闭时清理所有计时器
    const cleanupTimers = () => {
      Object.values(timers.value).forEach(timer => clearInterval(timer));
      timers.value = {};
    };

    // 监听对话框关闭事件
    watch(groupBuyDialogVisible, newValue => {
      if (!newValue) {
        cleanupTimers();
      }
    });

    // 组件卸载时清理计时器
    onUnmounted(() => {
      cleanupTimers();
    });
    const getRandomPastelColor = () => {
      // 生成柔和的随机颜色
      const hue = Math.floor(Math.random() * 360); // 随机色相
      const saturation = 25 + Math.random() * 20; // 较低的饱和度，使颜色更柔和
      const lightness = 85 + Math.random() * 10; // 较高的亮度，确保背景色淡雅
      return `hsl(${hue}, ${saturation}%, ${lightness}%)`;
    };
    const __returned__ = {
      API_BASE_URL,
      router,
      store,
      searchQuery,
      selectedSort,
      currentPage,
      itemsPerPage,
      sortedProducts,
      ads,
      goToProfile,
      fetchProductData,
      goToCart,
      goToOrders,
      userNickname,
      userAvatar,
      paginatedProducts,
      handlePageChange,
      applySearch,
      goHome,
      viewProductDetails,
      selectCategory,
      logout,
      groupBuyDialogVisible,
      myGroupBuys,
      timers,
      showMyGroupBuys,
      fetchMyGroupBuys,
      startGroupCountdown,
      formatGroupStatus,
      formatTime,
      copyInviteCode,
      getParticipantAvatar,
      cleanupTimers,
      getRandomPastelColor,
      ref,
      computed,
      onMounted,
      onUnmounted,
      watch,
      get ElCarousel() {
        return ElCarousel;
      },
      get ElCarouselItem() {
        return ElCarouselItem;
      },
      get ElButton() {
        return ElButton;
      },
      get ElMenu() {
        return ElMenu;
      },
      get ElMenuItem() {
        return ElMenuItem;
      },
      get ElSelect() {
        return ElSelect;
      },
      get ElOption() {
        return ElOption;
      },
      get ElRow() {
        return ElRow;
      },
      get ElCol() {
        return ElCol;
      },
      get ElCard() {
        return ElCard;
      },
      get ElPagination() {
        return ElPagination;
      },
      get ElDialog() {
        return ElDialog;
      },
      get ElMessage() {
        return ElMessage;
      },
      get useRouter() {
        return useRouter;
      },
      get useStore() {
        return useStore;
      },
      get axios() {
        return axios;
      },
      get User() {
        return User;
      },
      get ShoppingCart() {
        return ShoppingCart;
      },
      get List() {
        return List;
      },
      get People() {
        return People;
      },
      get SwitchButton() {
        return SwitchButton;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
